        try {
            await InternalScoring.LoadParameters();
            const view = await BuildVendorScoringView();
            view.InitPanes(layout);
            view.InitControls();
            await view.FillFormData();
        }
        catch (reason) {
            Log.Error("GlobalError : " + reason);
        }
