																			"*": {
																				"HTMLBanner__": {
																					"type": "HTML",
																					"data": false,
																					"stamp": 17,
																					"options": {
																						"label": "HTMLBanner",
																						"version": 1,
																						"htmlContent": "<input id=\"onBannerLoad\" type=\"hidden\" onclick=\"onBannerLoad(event);\">\n<input id=\"onNewScore\" type=\"hidden\" onclick=\"onNewScore(event);\">\n\n<div class=\"bannerContainer is-centered sys-helpers-banner\">\n\t<span id=\"bannerScore\">\n\t\t<div id=\"progressBarLoader\" class=\"pb-circleLoader-wrapper\">\n\t\t\t<div class=\"pb-circleLoader-inside\"></div>\n\t\t</div>\n\t</span>\n\t<span class=\"bannerMainTitle\">\n\t\t<div id=\"vendorNameLabel\" class=\"main-title\"></div>\n\t\t<div id=\"vendorNameValue\" class=\"sub-title\"></div>\n\t</span>\n</div>\n\n<script>\n\tfunction onBannerLoad(event)\n\t{\n\t\tdocument.getElementById(\"vendorNameLabel\").innerText = event.translation.vendorNameLabel;\n\t\tdocument.getElementById(\"vendorNameValue\").innerText = event.vendorNameValue;\n\t}\n\n\tfunction onNewScore(event)\n\t{\n\t\tvar value = parseFloat(event.scoreValue).toFixed(0);\n\t\tvar bannerScore = document.getElementById(\"bannerScore\");\n\t\t\n\t\tbannerScore.innerHTML = event.scoreValue && value >= 0 ? value.toString() : 'N/A';\n\t\tbannerScore.style.background = event.scoreColor;\n\t\tif (!event.scoreValue || value < 0 || value >= 100)\n\t\t{\n\t\t\tbannerScore.style.fontSize = \"20pt\";\n\t\t}\n\t}\n</script>",
																						"width": "100%",
																						"css": "@keyframes pb-spin {\n    0% {\n\t\ttransform: rotate(360deg);\n\t}\n\n    100% {\n\t\ttransform: rotate(0deg);\n\t}\n}\n\n.pb-circleLoader-wrapper {\n\twidth: 30px;\n\theight: 30px;\n\tborder-radius: 50%;\n\tposition: relative;\n\toverflow: hidden;\n\ttext-align: left;\n\tanimation: pb-spin 2s linear infinite;\n}\n\n.pb-circleLoader-inside {\n\twidth: 100%;\n\theight: 50%;\n\tposition: relative;\n\tmargin-top: 50%;\n\tbackground: linear-gradient(90deg, rgb(220, 220, 220), rgb(150, 150, 150));\n}\n\n.pb-circleLoader-inside:before {\n\tcontent: '';\n\twidth: 100%;\n\theight: 100%;\n\tposition: absolute;\n\tmargin-top: -50%;\n\tbackground: linear-gradient(90deg, rgb(50, 50, 50), rgb(160, 160, 160));\n}\n\n.pb-circleLoader-inside:after {\n\tcontent: '';\n\twidth: 80%;\n\theight: 160%;\n\tposition: absolute;\n\tmargin-top: -40%;\n\tmargin-left: 10%;\n\tbackground: white;\n\tborder-radius: 50%;\n}\n\n.bannerContainer {\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n}\n\n.bannerMainTitle {\n\ttext-align: left;\n}\n\n#bannerScore {\n\tborder-radius: 8px;\n\tfont-size: 30pt;\n\tcolor: white;\n\tbackground-color: white;\n\twidth: 60px;\n\theight: 60px;\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\tmargin-right: 20px;\n}"
																					}
																				}
																			}
																		}
																	}
																}
															}
														}
